require dirname(__DIR__).'/config/init.php';require CONF.'/db_bootstrap.php';use app\services\SpecialTyreFeedService as F;
if(PHP_OS_FAMILY!=='Windows')throw new RuntimeException('Local fixture only');$c=require CONF.'/config_db.php';if(!preg_match('/host=(?:localhost|127\.0\.0\.1)(?:;|$)/',$c['dsn']))throw new RuntimeException('Local DB only');$db=R::getPDO();$prefix='feed_stock_'.bin2hex(random_bytes(5));$product=$prefix.'_product';$mods=$prefix.'_modification';
try{$db->exec('CREATE TABLE '.$product.' (id INT,quantity INT,reserve INT) ENGINE=InnoDB');$db->exec('CREATE TABLE '.$mods.' (product_id INT,quantity INT) ENGINE=InnoDB');$db->exec('INSERT INTO '.$product.' VALUES(1,5,5),(2,0,5),(3,2,7),(4,-2,0)');$db->exec('INSERT INTO '.$mods.' VALUES(3,3)');$sql=str_replace(['product.','FROM modification m'],[$product.'.','FROM '.$mods.' m'],F::stock());$actual=$db->query('SELECT id,'.$sql.' AS available FROM '.$product.' ORDER BY id')->fetchAll(PDO::FETCH_KEY_PAIR);foreach([1=>5,2=>0,3=>5,4=>0] as $id=>$want)if((int)$actual[$id]!==$want)throw new RuntimeException('Free stock regression '.$id);echo "Feed stock: API free rest retained, reserve never subtracted twice, variants and nonnegative floor OK\n";}finally{$db->exec('DROP TABLE IF EXISTS '.$mods);$db->exec('DROP TABLE IF EXISTS '.$product);}
